\begin{lemma}\label{lem:f-word-normalization}
Let \(a=a_1\cdots a_r\) be a nonempty word of distinct positive integers, and
let \(\kappa(a)=\kappa_1\cdots\kappa_r\) be the decreasing rearrangement of the
letters of \(a\) and write
\[
a=a_L\,\kappa_1\,a_R,
\]
where \(a_L\) and \(a_R\) are the subwords to the left and to the right of
\(\kappa_1\), respectively. 
Let $\mathbf B_L =_{\mathcal I} f(a_L)$ and $\mathbf B_R =_{\mathcal I} f(a_R)$. Then, $f(a)$ is equivalent modulo ${\mathcal I}$ to a term in one of the following forms:
\begin{itemize}
    \item [$\cdot$] if $a_L,a_R\neq\emptyset$, then $f(a)=_{\mathcal I}(\mathbf 2^{\kappa_1}\circ_2 \mathbf B_R)\circ_1 \mathbf B_L$;
    \item [$\cdot$] if \(a_L=\emptyset\), then $f(a)=_{\mathcal I}\mathbf 2^{\kappa_1}\circ_2 \mathbf B_R$;
    \item [$\cdot$] if \(a_R=\emptyset\), then $f(a)=_{\mathcal I}\mathbf 2^{\kappa_1}\circ_1 \mathbf B_L$;
    \item [$\cdot$] if \(a=\kappa_1\), then \(f(a)=\mathbf 2^{\kappa_1}\).
\end{itemize}
\end{lemma}

\subsection{Operad structure}
We use the above results to endow the collection $\{\K_n\}_{n\geq 1}$ of Loday realizations (with standard weights) with an operad structure as follows.

\begin{definition}[Operad structure]
For any $n,m\geq 1$ and any $1\leq i \leq m$, we define the \emph{partial composition map} by
\[
\circ_i\ : \ \K_m\times \K_n
\To{\tr\times \id} \K_{(1,\ldots,n,\ldots,1)}\times \K_n
\Hto{\Theta}
\K_{n+m-1},
\]
where the last inclusion is given by the block permutation of the coordinates introduced in the proof of \cref{prop:PropertiesKLoday}.
\end{definition}

\skpt
\begin{theorem}\label{thm:MainOperad}
\begin{enumerate}
\item The collection $\{K_n\}_{n\geq 1}$ together with the partial composition maps $\circ_i$ form a~non-symmetric operad in the category $\PolySub$.

\item The maps $\{\triangle_n : K_n \to K_n\times K_n\}_{n\geq 1}$ form a morphism of non-symmetric operads in the category $\PolySub$.
\end{enumerate}
\end{theorem}

\begin{lemma}
    Let $F_T$ be a face of the graph multiplihedron $\mathcal{J}(L(P))$ associated to an acyclic tubing $T$ of the line graph of the Hasse diagram of $P$. Then $F_T$ intersects the evaluation space, which is the intersection of all the cycle hyperplanes.
\end{lemma}

\section{The magical formula}\label{sec:MagicalFormula}

\begin{theorem}[Magical formula]\label{thm:MagicFormula}
For any Loday realization of the associahedra, the approximation of the diagonal satisfies
\[{\im \triangle_n
=\bigcup_{\substack{\tp F\leq \bm G\\ \dim F+\dim G=n-2}} F\times G}.\]
